        --t-sub: #71767b;
        --t-line: #2f3336;
        --t-thread: #333639;
        box-shadow: none;
    }
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ===== 主帖：头像 + 名字 + id ===== */
.xt-header { align-items: flex-start !important; }
.xt-avatar {
    width: 52px;
    height: 52px;
    border-radius: 50% !important;
    border: none !important;
    object-fit: cover;
}
.xt-name {
    color: var(--t-text);
    font-size: 17px;
    font-weight: 800;
    line-height: 24px;
    margin-top: 2px;
}
/* 名字下面的 @id：往上提到头像右边（偏了就改这个 -28px） */
.xt-text-charHandle {
    background: none !important;
    margin-top: -28px !important;
    padding: 0 0 0 64px !important;
    height: 24px;
    font-size: 15px;
    line-height: 24px;
    color: var(--t-sub) !important;
    font-style: normal !important;
}
/* 右上角：仅自己可见（代替“关注”按钮） */
.xt-tags {
    position: absolute;
    top: 20px;
    right: 16px;
    margin: 0;
}
.xt-tag {
    background: var(--t-text) !important;
    color: var(--t-bg) !important;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 700;
    padding: 6px 14px;
}

/* ===== 主帖：正文和时间 ===== */
.xt-text-tweetText {
    background: none !important;
    padding: 14px 2px 0 !important;
    font-size: 20px;
    line-height: 1.5;
    color: var(--t-text) !important;
    font-style: normal !important;
    white-space: pre-wrap;
}
.xt-text-tweetMeta {
    background: none !important;
    padding: 14px 2px 10px !important;
    font-size: 14px;
    color: var(--t-sub) !important;
    font-style: normal !important;
}
.xt-divider {
    border: none !important;
    border-top: 1px solid var(--t-line) !important;
    background: none !important;
    height: 0 !important;
    margin: 0;
}

/* ===== 数据行：图标（用 mask 画，跟随文字颜色） ===== */
.xt-grid {
    background: none !important;
    border: none !important;
    gap: 0 !important;
}
.xt-grid-stat {
    display: flex !important;
    flex-direction: row-reverse;
    justify-content: flex-start;
    align-items: center;
    gap: 6px;
    background: none !important;
    border: none !important;
    padding: 0 !important;
}
.xt-grid-stat-value {
    font-size: 14px !important;
    font-weight: 400;
    color: var(--t-sub) !important;
}
.xt-grid-stat-value:empty { display: none; }
.xt-grid-stat-label {
    font-size: 0 !important;
    line-height: 0 !important;
    letter-spacing: 0 !important;
}
.xt-grid-stat-label::before {
    content: "";
    display: inline-block;
    width: 19px;
    height: 19px;
    background-color: var(--t-sub);
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    -webkit-mask-size: contain;
    mask-size: contain;
}
/* 主帖数据行（5 项） */
.xt-grid-5 {
    grid-template-columns: repeat(5, auto) !important;
    justify-content: space-between;
    padding: 12px 2px 14px !important;
    border-top: 1px solid var(--t-line) !important;
}
.xt-grid-5 .xt-grid-stat-value { font-size: 15px !important; }
.xt-grid-5 .xt-grid-stat-label::before { width: 22px; height: 22px; }
/* 评论数据行（6 项） */
.xt-grid-6 {
    grid-template-columns: repeat(6, auto) !important;
    justify-content: space-between;
    padding: 8px 0 0 !important;
    width: 100%;
    flex: 0 0 100%;
}
.xt-grid-6 .xt-grid-stat-value { font-size: 13px !important; }
.xt-grid-6 .xt-grid-stat-label::before { width: 18px; height: 18px; }
