/* 微信式独立引用，沿用对方气泡轮廓。 */
.chat-detail-screen {
  --reply-detached-name-suffix: "：";
  --reply-detached-name-color: #555555;
  --reply-detached-text-color: #555555;
}
.chat-detail-screen .msg-bubble-wrapper:has(.msg-reply-block-detached) .msg-reply-block {
  position: absolute !important;
  visibility: hidden !important;
  pointer-events: none !important;
}
.chat-detail-screen .msg-reply-block-detached {
  display: flex !important;
  order: 1;
  flex-direction: row !important;
  align-items: baseline !important;
  gap: 3px !important;
  box-sizing: border-box;
  width: fit-content !important;
  min-width: 34px !important;
  max-width: 100% !important;
  min-height: 27px;
  margin: 0 !important;
  padding: 4px 10px 6px !important;
  border: 1px solid transparent !important;
  box-shadow: none !important;
  color: #555555 !important;
  font-size: 12px !important;
  line-height: 1.35 !important;
}
.chat-detail-screen .msg-reply-detached-me { align-self: flex-end !important; }
/* 对方的独立引用保持左对齐。 */
.chat-detail-screen .msg-reply-detached-them { align-self: flex-start !important; }
.chat-detail-screen .msg-reply-block-detached :is(.msg-reply-detached-name, .msg-reply-detached-text, .msg-reply-detached-media) {
  min-width: 0;
  color: #555555 !important;
  -webkit-text-fill-color: #555555 !important;
  font-size: inherit !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.chat-detail-screen .msg-reply-block-detached .msg-reply-detached-name {
  flex: 0 0 auto;
  max-width: 40%;
}

/* 使用独立译文样式，原生翻译按钮透明覆盖原文气泡。 */
.chat-detail-screen {
  --translation-always-show: 1;
}
.chat-detail-screen :is(.bubble-me-custom, .bubble-them-custom, .msg-plain-me, .msg-plain-them):has(.msg-translation-wrapper) {
  position: relative !important;
}
.chat-detail-screen :is(.bubble-me-custom, .bubble-them-custom, .msg-plain-me, .msg-plain-them) .msg-translation-wrapper:not(:has(.msg-translation-detached)) {
  position: absolute !important;
  inset: 0 !important;
  z-index: 5;
  box-sizing: border-box;
  width: auto !important;
  height: auto !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  visibility: visible !important;
  pointer-events: auto !important;
}
.chat-detail-screen :is(.bubble-me-custom, .bubble-them-custom, .msg-plain-me, .msg-plain-them)
  .msg-translation-wrapper :is(button, [role="button"], [class*="translation-toggle" i], [class*="translation-btn" i]):not(.msg-translation-detached *, :has(.msg-translation-detached)) {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  z-index: 1;
  opacity: 0 !important;
  pointer-events: auto !important;
}
/* 有些版本把独立译文放在翻译容器内部，不能让它继承透明层。 */
.chat-detail-screen .msg-translation-wrapper:has(.msg-translation-detached) {
  display: contents !important;
}
.chat-detail-screen .msg-translation-detached:not([hidden], [aria-hidden="true"], [style*="display:none" i], [style*="display: none" i]) {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}
.chat-detail-screen .msg-translation-detached {
  box-sizing: border-box;
  width: fit-content !important;
  min-width: min(142px, 100%) !important;
  max-width: 100% !important;
  margin-top: 2px !important;
  margin-bottom: 9px !important;
}
.chat-detail-screen .msg-translation-detached-me { align-self: flex-end !important; }
.chat-detail-screen .msg-translation-detached-them { align-self: flex-start !important; }
.chat-detail-screen .msg-translation-detached-content {
  position: relative;
  box-sizing: border-box;
  padding: 8px 10px !important;
  border: 1px solid #dcdcdc !important;
  border-radius: 8px !important;
  background: #f1f1f1 !important;
  color: #252525 !important;
  box-shadow: none !important;
  font-size: 13px !important;
  line-height: 1.45 !important;
  overflow-wrap: anywhere;
}
.chat-detail-screen .msg-translation-detached-content::before {
  content: "✓";
  position: absolute;
  left: 10px;
  bottom: 9px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #666666;
  color: #fff;
  font: 8px/11px system-ui, sans-serif;
  text-align: center;
  pointer-events: none;
}
.chat-detail-screen .msg-translation-detached-content::after {
  content: "˵＞𖥦＜˵";
  display: block;
  margin-top: 5px;
  padding-left: 16px;
  color: #666666;
  font-size: 10px;
  line-height: 13px;
  pointer-events: none;
}

/* 胶囊底栏。菜单、语音、表情和发送沿用原生按钮。 */
.chat-detail-screen .input-area-custom {
  background: var(--input-area-bg) !important;
  padding-bottom: max(40px, calc(env(safe-area-inset-bottom, 0px) + 6px)) !important;
  border-top: 0 !important;
  box-shadow: none !important;
}
.chat-detail-screen .input-row-wrapper {
  --sb-footer-center: 18px;
  position: relative !important;
  box-sizing: border-box !important;
  display: flex !important;
  align-items: flex-start !important;
  width: 100% !important;
  min-height: 36px !important;
  padding: 0 84px 0 46px !important;
  gap: 0 !important;
  overflow: visible !important;
}
.chat-detail-screen .input-row-wrapper .input-action-bar-custom {
  position: static !important;
  box-sizing: border-box !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  min-height: 36px !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 0 !important;
  background: var(--input-box-bg) !important;
  border: 0 !important;
  border-radius: var(--input-box-radius) !important;
  box-shadow: none !important;
}
.chat-detail-screen .input-row-wrapper .input-btns-right {
  display: contents !important;
  position: static !important;
}
.chat-detail-screen .input-row-wrapper .input-box-custom {
  box-sizing: border-box !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  width: 100% !important;
  min-height: 36px !important;
  padding: 8px 33px 8px 11px !important;
  text-align: left !important;
  text-indent: 0 !important;
  border: 0 !important;
  border-radius: var(--input-box-radius) !important;
  background: var(--input-box-bg) !important;
  box-shadow: none !important;
}
.chat-detail-screen .input-area-custom :is(.input-box-custom, textarea, input[type="text"])::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}
.chat-detail-screen .input-row-wrapper :is(.input-btn-plus, .input-btn-mic, .input-btn-sticker, .stop-btn-custom, .input-btn-ai),
.chat-detail-screen .input-row-wrapper .send-btn-custom,
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-ai, .send-btn-custom, .stop-btn-custom))::after {
  position: absolute !important;
  top: var(--sb-footer-center) !important;
  bottom: auto !important;
  transform: translateY(-50%) !important;
  box-sizing: border-box !important;
  width: 34px !important;
  min-width: 0 !important;
  height: 34px !important;
  min-height: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  z-index: 2;
}
.chat-detail-screen .input-row-wrapper :is(.input-btn-plus, .input-btn-mic, .input-btn-sticker) {
  display: grid !important;
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: auto !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-plus {
  left: 0 !important;
  right: auto !important;
  background: var(--plus-btn-icon) center / 23px 23px no-repeat !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-sticker {
  left: auto !important;
  right: 38px !important;
  background: var(--sticker-btn-icon) center / 22px 22px no-repeat !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-ai,
.chat-detail-screen .input-row-wrapper .send-btn-custom,
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-ai, .send-btn-custom, .stop-btn-custom))::after {
  left: auto !important;
  right: 0 !important;
  background: var(--sb-footer-send-icon) center / 22px 22px no-repeat !important;
}
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-ai, .send-btn-custom, .stop-btn-custom))::after {
  content: "" !important;
  opacity: 1 !important;
  pointer-events: none !important;
}
/* 原生 AI 键优先占右槽，保留送出并触发回复的原有行为。 */
.chat-detail-screen .input-row-wrapper :is(.input-btn-ai, .send-btn-custom) {
  z-index: 6 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  opacity: 1 !important;
  filter: none !important;
  touch-action: manipulation;
}
.chat-detail-screen .input-row-wrapper :is(.input-btn-ai, .send-btn-custom) > *,
.chat-detail-screen .input-row-wrapper :is(.input-btn-ai, .send-btn-custom)::before,
.chat-detail-screen .input-row-wrapper :is(.input-btn-ai, .send-btn-custom)::after {
  visibility: hidden !important;
  pointer-events: none !important;
}
.chat-detail-screen .input-row-wrapper .stop-btn-custom {
  left: auto !important;
  right: 0 !important;
  z-index: 9 !important;
  pointer-events: auto !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-mic {
  left: auto !important;
  right: 84px !important;
  width: 29px !important;
  background: var(--mic-btn-icon) center / 18px 18px no-repeat !important;
  opacity: 1 !important;
  pointer-events: auto !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-mic > * {
  visibility: hidden !important;
  pointer-events: none !important;
}
.chat-detail-screen .input-row-wrapper .input-btn-mic::before,
.chat-detail-screen .input-row-wrapper .input-btn-mic::after {
  content: none !important;
}
/* 同时有普通发送键时，给它单独留位，避免覆盖原生 AI 键。 */
.chat-detail-screen .input-row-wrapper:has(.input-btn-ai) .send-btn-custom {
  left: 34px !important;
  right: auto !important;
  width: 12px !important;
  opacity: 0 !important;
}
.chat-detail-screen .input-row-wrapper:has(.input-btn-ai) .send-btn-custom:focus-visible {
  opacity: 1 !important;
}
.chat-detail-screen .input-row-wrapper :is(.input-btn-plus, .input-btn-sticker) > * {
  visibility: hidden !important;
}
.chat-detail-screen .input-row-wrapper :is(.input-btn-plus, .input-btn-sticker)::before,
.chat-detail-screen .input-row-wrapper :is(.input-btn-plus, .input-btn-sticker)::after {
  content: none !important;
}

/* 原生按钮暂未渲染时保留对应图标位置。 */
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-mic)) .input-action-bar-custom::before,
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-sticker)) .input-action-bar-custom::after {
  content: "" !important;
  position: absolute !important;
  top: var(--sb-footer-center);
  width: 34px;
  height: 34px;
  transform: translateY(-50%);
  z-index: 2;
  pointer-events: none;
}
.chat-detail-screen .input-row-wrapper:not(:has(.input-btn-mic)) .input-action-bar-custom::before {
