  background:var(--ry-card) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%239a9a9a' stroke-width='2' stroke-linecap='round'><circle cx='11' cy='11' r='7'/><line x1='21' y1='21' x2='16.5' y2='16.5'/></svg>") no-repeat calc(50% - 20px) center / 14px 14px !important;
  border:1px solid var(--ry-search-line) !important; border-radius:10px;
  color:var(--ry-search-ink); font-size:14px; letter-spacing:.02em; line-height:1;
  pointer-events:none; z-index:2;
}

.chat-detail-screen .header-profile-section{
  position:static !important; transform:none !important;
  margin:0 !important; padding:0 !important; background:transparent !important;
}
.chat-detail-screen .header-profile-section::after{
  content:var(--ry-sub-text) !important; display:block !important;
  position:absolute !important;
  left:32px; top:calc(var(--ry-top) + 56px); max-width:66vw;
  font-size:11px; line-height:14px; color:var(--ry-sub);
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; letter-spacing:.02em;
  pointer-events:none; z-index:4;
}
.chat-detail-screen .header-profile-section::before{ content:none !important; }
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-subtitle{ display:none !important; }

.chat-detail-screen .header-avatar-container{
