  padding:0 !important; margin:0 !important; transform:none !important;
  background:transparent !important; background-image:none !important;
  border:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:transparent !important; opacity:1 !important; visibility:visible !important;
  pointer-events:auto !important; cursor:pointer !important; z-index:8 !important;
  -webkit-tap-highlight-color:transparent !important;
}
.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-back, .header-btn-info, .header-btn-phone, .header-btn-video)::before{ content:none !important; }
.chat-detail-screen .glass-header:has(.header-profile-section) :is(.header-btn-info, .header-btn-phone, .header-btn-video) > *,
.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-back > *:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){
  opacity:0 !important; pointer-events:none !important;
