.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-title::before,
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .chat-header-title::after{ content:none !important; }

.chat-detail-screen .glass-header:has(.header-profile-section) .header-btn-info{
