/* --- 1. 顶栏背景：白底，底部留出灰栏的位置 --- */
div.chat-detail-screen .chat-header-custom:has(.header-profile-section) {
  position: relative !important;
  z-index: 10 !important;
  box-sizing: border-box !important;
  height: auto !important;
  padding-left: var(--cx-pad-x) !important;
  padding-right: var(--cx-pad-x) !important;
  padding-bottom: calc(var(--cx-strip-h) + var(--cx-tri-h) + 4px) !important;
  background: var(--cx-hdr-bg) !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  overflow: visible !important;
}

/* 内层 .glass-header 透明 */
div.chat-detail-screen .chat-header-custom:has(.header-profile-section) .glass-header {
  background: transparent !important;
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* 布局：第一行 返回 …… 设置，中间一条分割线，下面 头像 + 名字
   头像 + 名字那行正常排在顶栏里，占满整行；
   返回、设置不排队，直接用绝对定位放到它上面，所以不管 App 里这几个按钮包了几层都不会挤成一排 */
div.chat-detail-screen:not(#_cx) .chat-header-custom:has(.header-profile-section) *:has(.header-btn-back, .header-action-btn) {
  position: static !important;
  transform: none !important;
  filter: none !important;
  contain: none !important;
}
/* 名字那一路的外层都撑满一整行 */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-header-custom:has(.header-profile-section) *:has(.header-profile-section) {
  flex: 1 1 100% !important;
  width: 100% !important;
  min-width: 0 !important;
  max-width: none !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
}

/* 头像 + 名字：上面空出按键那一行；上边框就是分割线 */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-header-custom .header-profile-section {
  flex: 1 1 100% !important;
  width: 100% !important;
  margin-top: calc(var(--cx-btn) + var(--cx-row-gap) - var(--cx-lift)) !important;
  padding-top: var(--cx-row-gap) !important;
  border-top: 0.5px solid var(--cx-divider) !important;
}

/* 返回：左上，固定在分割线上面 */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-header-custom:has(.header-profile-section) .header-btn-back {
  position: absolute !important;
  left: var(--cx-pad-x) !important;
  right: auto !important;
  top: auto !important;
  bottom: var(--cx-btn-bottom) !important;
  margin: 0 0 0 calc(-10px + var(--cx-btn-in)) !important;
  z-index: 5 !important;
}
/* 设置：右上，和返回同一高度 */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-header-custom:has(.header-profile-section) *:has(> .header-action-btn):not(:has(.header-profile-section)) {
  position: absolute !important;
  right: var(--cx-pad-x) !important;
  left: auto !important;
  top: auto !important;
  bottom: var(--cx-btn-bottom) !important;
  width: auto !important;
  height: var(--cx-btn) !important;
  margin: 0 calc(-9px + var(--cx-btn-in)) 0 0 !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  z-index: 5 !important;
}

/* --- 2. 三角 + 淡灰栏 + 「Can I kiss u ?」 --- */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-header-custom:has(.header-profile-section)::before {
  content: var(--cx-main-text) !important;
  display: block !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  top: auto !important;
  width: auto !important;
  height: calc(var(--cx-strip-h) + var(--cx-tri-h)) !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: calc(var(--cx-tri-h) + 6px) var(--cx-pad-x) 0 !important;
  background:
