}
/* 真实图片 */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) :is(.msg-image-card, .msg-image-wrapper):not(.msg-reply-block *) {
  max-width: var(--cxp-max-w) !important;
