    /* 下面手写那条：浅灰带一点脏 */
    linear-gradient(180deg, #E6E6E8 0%, #EFEFF0 40%, #E3E3E5 100%) no-repeat 4px calc(var(--cxt-ph) - 25px) / calc(var(--cxt-pw) - 8px) 21px,
    /* 拍立得底板 */
    linear-gradient(180deg, #F4F4F5 0%, #ECECEE 100%) no-repeat 0 0 / var(--cxt-pw) var(--cxt-ph) !important;
