}
/* 对方：箭头在最右，朝右；整行贴左边 */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) :is(.bubble-them-custom, .msg-plain-them) .msg-reply-block::after {
  content: var(--cxq-label-them) !important;
  left: 2px !important;
  right: auto !important;
  padding: 0 calc(var(--cxq-label-size) + 6px) 0 0 !important;
  background: var(--cxq-arrow) right center / calc(var(--cxq-label-size) + 2px) calc(var(--cxq-label-size) + 2px) no-repeat !important;
  text-align: left !important;
}

/* --- 4. 带引用的那一行：上面留出引用框 + 英文的位置 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-bubble-wrapper:has(.msg-reply-block) {
  margin-top: calc(var(--cxq-h) + var(--cxq-gap) + var(--cxq-label-size) + 3px + var(--cxq-label-gap) + 6px) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【引用预览条 · 底栏里面，在输入框上面】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ┌─────────────────────────────┐
   │ ✕  对方备注        ← 深灰    │  ← 预览条
   │    被引用的文字    ← 浅灰    │
   │ ─────────────────────────── │
   │ 🔍 消息…               [➤]  │
   │ ⌂ │ 书签+ │ 方框+ │ 铃铛 │ ⇄ │
   └─────────────────────────────┘
   出现预览条时底栏上面加高，输入框和第二行位置不动、整栏往上抬
   名字用 App 给的 --char-name（对方备注） */

/* --- 1. 有引用：底栏上面加高，留出预览条的位置 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom:has(.input-reply-preview-bar) {
  padding-top: calc(var(--cxr-top) + var(--cxr-h) + var(--cxr-gap)) !important;
}

/* --- 2. 预览条本体：没有底色，下面一条细线 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-bar {
  position: absolute !important;
  left: var(--cb-pad-x) !important;
  right: var(--cb-pad-x) !important;
  top: var(--cxr-top) !important;
  bottom: auto !important;
  z-index: 5 !important;
  display: block !important;
  box-sizing: border-box !important;
  width: auto !important;
  height: var(--cxr-h) !important;
  min-height: 0 !important;
  max-height: var(--cxr-h) !important;
  margin: 0 !important;
  padding: 1px 4px 0 30px !important;
  border: none !important;
  border-bottom: 0.5px solid var(--cxr-line) !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transform: none !important;
  overflow: hidden !important;
  pointer-events: auto !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-bar::before,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-bar::after {
  content: none !important;
  display: none !important;
}

/* --- 3. 内容层：竖着排两行，左边竖线去掉 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-content {
  display: block !important;
  position: static !important;
  min-width: 0 !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-content::before,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-content::after {
  content: none !important;
  display: none !important;
}

/* --- 4. 第一行：对方备注（深灰） --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-name {
  display: block !important;
  height: 17px !important;
  margin: 0 !important;
  padding: 0 !important;
  text-indent: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  background: none !important;
  border: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-name * {
  display: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-name::after {
  content: none !important;
  display: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-name::before {
  content: var(--char-name) !important;
