  padding: 0 !important;
  text-indent: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  background: none !important;
  border: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom :is(.input-reply-preview-text, .input-reply-preview-text *) {
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 16px !important;
  color: var(--cxr-text-color) !important;
  -webkit-text-fill-color: var(--cxr-text-color) !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-media {
  display: none !important;
}

/* --- 6. 关闭键：挪到最左边，上下居中 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-close {
  position: absolute !important;
  top: 50% !important;
  left: -4px !important;
  right: auto !important;
  bottom: auto !important;
  transform: translateY(-50%) !important;
  display: block !important;
  box-sizing: border-box !important;
  width: 28px !important;
  height: 28px !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 50% !important;
  background: var(--cxr-x) center / 13px 13px no-repeat !important;
  box-shadow: none !important;
  opacity: 1 !important;
  font-size: 0 !important;
  color: transparent !important;
  cursor: pointer !important;
  z-index: 2 !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-close > * {
  display: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-close::before,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx) .input-area-custom .input-reply-preview-close::after {
  content: none !important;
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【翻译 · 字幕条】照 VacantMint ◆◆◆◆◆◆◆◆◆◆◆◆ */
/*        [ 난 널 싫어해, 나랑 말 하지 마 ]
               ▇我讨厌你，你别跟我说话▇      ← 我方：压在气泡底边，靠右
   [ 애교 부리면서 문제 피우는 거만 알아 ]
     ▇就知道撒娇逃避问题▇                    ← 对方：压在气泡底边，靠左
   一行不动；两行起整条自动往上缩，压住原文一点
   越靠上的消息层级越高，上一条的字幕盖得住下一条气泡，不会被挡住
   :not(#_cx) 叠很多层是为了压过气泡里 * 的通配颜色，不要删 */

/* --- 1. 气泡里的原翻译块不要 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-wrapper {
  display: none !important;
}

/* --- 2. 气泡外的翻译块：以消息行底边定位，往上压进气泡 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-bubble-wrapper:has(.msg-translation-detached) {
  position: relative !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached {
  display: block !important;
  position: absolute !important;
  top: calc(100% + var(--cxt2-overlap)) !important;
  bottom: auto !important;
  z-index: 10 !important;
  width: max-content !important;
  min-width: 0 !important;
  max-width: var(--cxt2-max-w) !important;
  margin: 0 !important;
  padding: 0 0 3px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: var(--cxt2-size) !important;
  line-height: 1.6 !important;
  box-sizing: border-box !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached::before,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached::after {
  content: none !important;
  display: none !important;
}
/* 我方靠右（让过我方头像）/ 对方靠左（让过对方头像） */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-me {
  right: calc(var(--cx-msg-avatar) + var(--cx-msg-avatar-gap) + var(--cxt2-inset-me)) !important;
  left: auto !important;
  text-align: right !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-them {
  left: calc(var(--cx-msg-avatar) + var(--cx-msg-avatar-gap) + var(--cxt2-inset-them)) !important;
  right: auto !important;
  text-align: left !important;
}
/* 一行不动；两行起整条自动往上缩 */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) :is(.msg-translation-detached-me, .msg-translation-detached-them) {
  transform: translateY(clamp(var(--cxt2-lift), calc(26px - 100%), 0px)) !important;
}

/* --- 3. 字幕条本体：行内背景，多行之间不留缝 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-content {
  display: inline !important;
  -webkit-box-decoration-break: clone !important;
  box-decoration-break: clone !important;
  background: var(--cxt2-bg) !important;
  color: var(--cxt2-text) !important;
  -webkit-text-fill-color: var(--cxt2-text) !important;
  font-size: var(--cxt2-size) !important;
  font-weight: 500 !important;
  line-height: 1.6 !important;
  padding: 3px 5px !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  white-space: normal !important;
  word-break: break-word !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-content * {
  display: inline !important;
  color: var(--cxt2-text) !important;
  -webkit-text-fill-color: var(--cxt2-text) !important;
  font-size: var(--cxt2-size) !important;
  background: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-content::before,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached-content::after,
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-translation-detached :is(svg, img) {
  content: none !important;
  display: none !important;
}

/* --- 4. 间距：每组最后一条多留出字幕的位置 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-bubble-wrapper:has(.msg-translation-detached):not(.is-last):not(.is-single) {
  margin-bottom: var(--cx-gap-in) !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .msg-bubble-wrapper:is(.is-last, .is-single):has(.msg-translation-detached) {
  margin-bottom: calc(var(--cx-gap-out) + var(--cxt2-reserve)) !important;
}

/* --- 5. 层级梯子：越靠上的消息层级越高，上一条的字幕才盖得住下一条气泡 --- */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-message-list-custom {
  isolation: isolate !important;
}
