.chat-message-list-custom>:nth-last-child(22){z-index:22!important}
.chat-message-list-custom>:nth-last-child(23){z-index:23!important}
.chat-message-list-custom>:nth-last-child(24){z-index:24!important}
.chat-message-list-custom>:nth-last-child(25){z-index:25!important}
.chat-message-list-custom>:nth-last-child(26){z-index:26!important}
.chat-message-list-custom>:nth-last-child(27){z-index:27!important}
.chat-message-list-custom>:nth-last-child(28){z-index:28!important}
.chat-message-list-custom>:nth-last-child(29){z-index:29!important}
.chat-message-list-custom>:nth-last-child(30){z-index:30!important}
.chat-message-list-custom>:nth-last-child(31){z-index:31!important}
.chat-message-list-custom>:nth-last-child(32){z-index:32!important}
.chat-message-list-custom>:nth-last-child(33){z-index:33!important}
.chat-message-list-custom>:nth-last-child(34){z-index:34!important}
.chat-message-list-custom>:nth-last-child(35){z-index:35!important}
