/* 行里面不再分层：字幕条（10）在同一行里压住自己的气泡 */
div.chat-detail-screen:not(#_cx):not(#_cx) .chat-message-list-custom > div > div,
div.chat-detail-screen:not(#_cx):not(#_cx) .msg-bubble-wrapper {
  z-index: auto !important;
  isolation: auto !important;
  will-change: auto !important;
  animation-fill-mode: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【语音 · 转文字面板】照 VacantMint ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ┌──────────────────────┐
   │ 声波 ……         4"  │ ← 语音条：圆角气泡，颜色和文字气泡一样
   └──────────────────────┘
   ┌──────────────────────┐
   │ 语音转文字            │ ← 左上角小标题
   │  ──────────────────  │ ← 分割线，左右各缩进
   │ 转写出来的文字…       │
   └──────────────────────┘ ← 很淡的灰，在气泡外面单独一块，点语音条展开 / 收起
   时间 + 已读挂在语音条下面，转文字面板上面
   :not(#_cx) 叠很多层是为了压过气泡规则，不要删 */

/* --- 1. 外层气泡去壳：外观挪到语音条上 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.voice-msg) {
  display: flex !important;
  flex-direction: column !important;
  position: relative !important;
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  min-width: 0 !important;
  overflow: visible !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) :is(.bubble-me-custom, .msg-plain-me):has(.voice-msg) {
  align-items: flex-end !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) :is(.bubble-them-custom, .msg-plain-them):has(.voice-msg) {
  align-items: flex-start !important;
}

/* --- 2. 语音容器：竖排，语音条在上、面板在下 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg {
  --voice-download-display: none !important;
  --voice-toggle-display: block !important;
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 0 !important;
  width: fit-content !important;
  min-width: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg-me   { align-items: flex-end !important; }
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg-them { align-items: flex-start !important; }

/* --- 3. 语音条：圆角气泡，声波 + 时长 --- */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg .voice-controls-row {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 8px !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: max(var(--cxv-min-w), var(--voice-len-base, 0px)) !important;
  height: var(--cxv-row-h) !important;
  min-height: var(--cxv-row-h) !important;
  margin: 0 !important;
  padding: 0 14px !important;
  border: none !important;
  border-radius: var(--cx-bubble-r) !important;
  box-shadow: none !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg-me .voice-controls-row {
  background: var(--cx-me-bg) !important;
}
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg-them .voice-controls-row {
  background: var(--cx-them-bg) !important;
}
/* 声波画在语音条 ::before 上，颜色跟文字走 */
div.chat-detail-screen:not(#_cx):not(#_cx):not(#_cx):not(#_cx):not(#_cx) .voice-msg .voice-controls-row::before {
  content: "" !important;
  display: block !important;
  position: static !important;
